import csv, re
from collections import Counter
rows = []
with open('/workspace/build-downgrade/study/3.thematic-analysis/labeled_data.csv','r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append(r)

mapping = {
    'go build':'Go Build', 'go build"':'Go Build', 'go build""':'Go Build',
    'go build"""':'Go Build', 'go build ' :'Go Build',
    'make':'Make', 'cmake':'CMake', 'nix':'Nix', 'google cloud build':'Google Cloud Build',
    'google cloud build ':'Google Cloud Build', 'google cloud build"':'Google Cloud Build',
    'swift pm':'SPM', 'swiftpm':'SPM', 'swift pm"':'SPM', 'spm':'SPM',
    'setuptools':'Setuptools', 'mage':'Mage', 'sbt':'SBT', 'gradle':'Gradle'
}

counts = Counter()
others = []
for r in rows:
    raw = r['replaced-by'] if 'replaced-by' in r else r.get('replaced_by','')
    if not raw or raw.strip()=='' or raw.strip().lower()=='nan':
        others.append(raw)
        continue
    # take first technology token by splitting on '+' or ',' or '/' or '\\n'
    first = re.split(r'\+|,|/|\\n', raw)[0].strip()
    # remove parentheses content
    first = re.sub(r'\(.*?\)','', first).strip()
    key = first.lower()
    # normalize some common variants
    key = key.replace('  ',' ')
    if key in mapping:
        counts[mapping[key]] += 1
    else:
        # try more heuristics
        if 'go' in key and 'build' in key:
            counts['Go Build'] += 1
        elif 'cmake' in key:
            counts['CMake'] += 1
        elif 'make' in key:
            counts['Make'] += 1
        elif 'google' in key and 'cloud' in key:
            counts['Google Cloud Build'] += 1
        elif 'nix' in key:
            counts['Nix'] += 1
        elif 'swift' in key or 'spm' in key or 'swift pm' in key:
            counts['SPM'] += 1
        elif 'mage' in key:
            counts['Mage'] += 1
        elif 'sbt' in key:
            counts['SBT'] += 1
        elif 'setuptools' in key or 'python' in key:
            counts['Setuptools'] += 1
        elif 'gradle' in key:
            counts['Gradle'] += 1
        else:
            counts[first] += 1

print('Counts:')
for k,v in counts.most_common():
    print(f'{k}: {v}')
print('Total rows processed:', len(rows))
